<?php require __DIR__.'/app/bootstrap.php';if(logged_in()){header('Location: '.base_url('dashboard'));exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$now=time();$a=$_SESSION['login_attempts']??[];$a=array_values(array_filter($a,fn($t)=>$t>$now-900));if(count($a)>=8)$error='Demasiados intentos. Espera unos minutos.';else{$email=mb_strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');$u=db_one($pdo,'SELECT * FROM dg_admin_users WHERE email=? LIMIT 1',[$email]);if($u&&(int)$u['active']===1&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);unset($_SESSION['login_attempts']);$_SESSION['dg_user']=['id'=>$u['id'],'email'=>$u['email'],'full_name'=>$u['full_name'],'role'=>$u['role'],'profile_photo'=>$u['profile_photo']??null];$pdo->prepare('UPDATE dg_admin_users SET last_login_at=UTC_TIMESTAMP() WHERE id=?')->execute([$u['id']]);header('Location: '.base_url('dashboard'));exit;}$_SESSION['login_attempts']=array_merge($a,[$now]);$error='Correo o contraseña incorrectos.';}}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | DoggieBot CRM</title><?php $css=__DIR__.'/assets/css/app.css';$v=is_file($css)?filemtime($css):'1';?><link rel="stylesheet" href="<?=h(base_url('assets/css/app.css?v='.$v))?>"></head><body class="login-page"><div class="login-shell"><section class="login-hero"><div class="hero-overlay"></div><div class="hero-content"><span class="mini-pill">DoggieBot · CRM</span><h1>Pedidos, reservaciones y atención desde un solo lugar.</h1><p>DoggieBot centraliza pedidos Pick&Go, reservaciones, facturación, eventos y seguimiento de clientes.</p></div></section><section class="login-side"><div class="login-card"><img class="login-logo" src="<?=h(base_url('assets/img/logo.png'))?>" alt="Los Dogos"><h2>Bienvenido</h2><p>Ingresa con tu correo electrónico.</p><?php if($error):?><div class="alert danger"><?=h($error)?></div><?php endif;?><form method="post"><?=csrf_input()?><label>Correo electrónico<input type="email" name="email" required autocomplete="username"></label><label>Contraseña<div class="password-wrap"><input id="pass" type="password" name="password" required autocomplete="current-password"><button type="button" class="eye" onclick="const p=document.getElementById('pass');p.type=p.type==='password'?'text':'password'">👁</button></div></label><button class="btn primary wide">Iniciar sesión</button></form><small class="login-foot">Acceso exclusivo para personal autorizado.</small></div></section></div></body></html>